using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using EduSphere.Web.Security;
using EduSphere.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.Enterprise;
[Authorize(Policy=AuthorizationPolicies.HostelManager)]
public sealed class HostelOperationsModel(TenantDbContext db,IBranchAccessService branchAccess,IHostelDepthService service,IFinanceAccountingService finance):PageModel
{
 public IReadOnlyList<Branch> Branches{get;private set;}=[];public IReadOnlyList<HostelBlock> Blocks{get;private set;}=[];public IReadOnlyList<HostelRoom> Rooms{get;private set;}=[];public IReadOnlyList<HostelAllocation> Allocations{get;private set;}=[];public IReadOnlyList<HostelMessMenu> Menus{get;private set;}=[];public IReadOnlyList<HostelMessAttendance> MessAttendance{get;private set;}=[];public IReadOnlyList<HostelMessBill> MessBills{get;private set;}=[];public IReadOnlyList<HostelVisitorLog> Visitors{get;private set;}=[];public IReadOnlyList<HostelGatePass> GatePasses{get;private set;}=[];public IReadOnlyList<HostelMaintenanceRequest> Maintenance{get;private set;}=[];public IReadOnlyList<HostelMaintenanceEscalation> Escalations{get;private set;}=[];public IReadOnlyList<HostelRoomInspection> Inspections{get;private set;}=[];public IReadOnlyList<HostelClearanceRequest> Clearances{get;private set;}=[];public IReadOnlyList<OccupancyForecastRow> Forecast{get;private set;}=[];
 [BindProperty]public MenuInput Menu{get;set;}=new();[BindProperty]public MealInput Meal{get;set;}=new();[BindProperty]public BillInput Bill{get;set;}=new();[BindProperty]public GateInput Gate{get;set;}=new();[BindProperty]public InspectionInput Inspection{get;set;}=new();[BindProperty]public DamageInput Damage{get;set;}=new();[BindProperty]public ClearanceInput Clearance{get;set;}=new();[TempData]public string? Feedback{get;set;}
 public sealed class MenuInput{[Required]public Guid? BranchId{get;set;}public Guid? HostelBlockId{get;set;}public DateOnly MenuDate{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);public HostelMealType MealType{get;set;}[Required]public string MenuItems{get;set;}="";public bool IsVegetarian{get;set;}public string? AllergenNotes{get;set;}public decimal GuestPrice{get;set;}}
 public sealed class MealInput{[Required]public Guid? HostelAllocationId{get;set;}public DateOnly AttendanceDate{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);public HostelMealType MealType{get;set;}public MessAttendanceStatus Status{get;set;}=MessAttendanceStatus.Present;}
 public sealed class BillInput{[Required]public Guid? HostelAllocationId{get;set;}public DateOnly From{get;set;}=new(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1);public DateOnly To{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);[Range(0,10000)]public decimal RatePerMeal{get;set;}=75;}
 public sealed class GateInput{[Required]public Guid? HostelAllocationId{get;set;}[Required]public string Reason{get;set;}="";public DateTime PlannedOutOn{get;set;}=DateTime.Now.AddHours(1);public DateTime PlannedReturnOn{get;set;}=DateTime.Now.AddHours(6);}
 public sealed class InspectionInput{[Required]public Guid? HostelRoomId{get;set;}public DateTime ScheduledOn{get;set;}=DateTime.Now.AddDays(1);}
 public sealed class DamageInput{[Required]public Guid? InspectionId{get;set;}public Guid? HostelAllocationId{get;set;}[Required]public string Description{get;set;}="";public decimal EstimatedCost{get;set;}public decimal ChargedAmount{get;set;}public bool StudentLiable{get;set;}}
 public sealed class ClearanceInput{[Required]public Guid? HostelAllocationId{get;set;}public DateOnly VacationFrom{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow.AddDays(1));public DateOnly? ExpectedReturnOn{get;set;}public bool IsFinalCheckout{get;set;}}
 public async Task OnGetAsync()=>await Load();
 public async Task<IActionResult> OnPostMenuAsync(){db.HostelMessMenus.Add(new(){BranchId=Menu.BranchId!.Value,HostelBlockId=Menu.HostelBlockId,MenuDate=Menu.MenuDate,MealType=Menu.MealType,MenuItems=Menu.MenuItems,IsVegetarian=Menu.IsVegetarian,AllergenNotes=Menu.AllergenNotes,GuestPrice=Menu.GuestPrice});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostMealAsync(){var allocation=await db.HostelAllocations.SingleAsync(x=>x.Id==Meal.HostelAllocationId);var row=await db.HostelMessAttendances.FirstOrDefaultAsync(x=>x.HostelAllocationId==allocation.Id&&x.AttendanceDate==Meal.AttendanceDate&&x.MealType==Meal.MealType);if(row is null)db.Add(new HostelMessAttendance{TenantId=allocation.TenantId,BranchId=allocation.BranchId,HostelAllocationId=allocation.Id,AttendanceDate=Meal.AttendanceDate,MealType=Meal.MealType,Status=Meal.Status,RecordedByUserId=UserId()});else row.Status=Meal.Status;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostBillAsync(){var bill=await service.GenerateMessBillAsync(Bill.HostelAllocationId!.Value,Bill.From,Bill.To,Bill.RatePerMeal,HttpContext.RequestAborted);Feedback=$"Mess bill and finance invoice created for {bill.Amount:N2}.";return RedirectToPage();}
 public async Task<IActionResult> OnPostVisitorStatusAsync(Guid id,HostelVisitorStatus status){var v=await db.HostelVisitorLogs.FindAsync(id);if(v is null)return NotFound();if(status==HostelVisitorStatus.Approved){v.ApprovedByUserId=UserId();v.ApprovedOn=DateTime.UtcNow;}else if(status==HostelVisitorStatus.CheckedIn){if(v.Status!=HostelVisitorStatus.Approved)throw new InvalidOperationException("Visitor approval is required before security check-in.");v.CheckInOn=DateTime.UtcNow;v.CheckedInByUserId=UserId();}else if(status==HostelVisitorStatus.CheckedOut){if(v.Status!=HostelVisitorStatus.CheckedIn)throw new InvalidOperationException("Only checked-in visitors can check out.");v.CheckOutOn=DateTime.UtcNow;v.CheckedOutByUserId=UserId();}v.Status=status;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostGateAsync(){var a=await db.HostelAllocations.SingleAsync(x=>x.Id==Gate.HostelAllocationId);db.HostelGatePasses.Add(new(){TenantId=a.TenantId,BranchId=a.BranchId,HostelAllocationId=a.Id,Reason=Gate.Reason,PlannedOutOn=Gate.PlannedOutOn.ToUniversalTime(),PlannedReturnOn=Gate.PlannedReturnOn.ToUniversalTime()});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostGateStatusAsync(Guid id,GatePassStatus status,string? notes){var pass=await db.HostelGatePasses.FindAsync(id);if(pass is null)return NotFound();if(status==GatePassStatus.WardenApproved){pass.ApprovedByUserId=UserId();pass.ApprovedOn=DateTime.UtcNow;}if(status==GatePassStatus.CheckedOut){if(pass.Status is not (GatePassStatus.WardenApproved or GatePassStatus.ParentApproved))throw new InvalidOperationException("The gate pass must be approved before checkout.");pass.ActualOutOn=DateTime.UtcNow;}if(status==GatePassStatus.Returned)pass.ActualReturnOn=DateTime.UtcNow;pass.Status=status;pass.DecisionNotes=notes;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostMaintenanceAsync(Guid id,HostelMaintenanceStatus status,string? resolution){var item=await db.HostelMaintenanceRequests.FindAsync(id);if(item is null)return NotFound();if(status==HostelMaintenanceStatus.InProgress&&item.FirstResponseOn is null)item.FirstResponseOn=DateTime.UtcNow;if(status==HostelMaintenanceStatus.Resolved)item.ResolvedOn=DateTime.UtcNow;item.Status=status;item.ResolutionNotes=resolution;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostEscalateAsync(){await service.EscalateBreachedMaintenanceAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostInspectionAsync(){var room=await db.HostelRooms.SingleAsync(x=>x.Id==Inspection.HostelRoomId);db.HostelRoomInspections.Add(new(){TenantId=room.TenantId,BranchId=room.BranchId,HostelRoomId=room.Id,ScheduledOn=Inspection.ScheduledOn.ToUniversalTime()});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostCompleteInspectionAsync(Guid id,int cleanlinessScore,int safetyScore,string? findings){var x=await db.HostelRoomInspections.FindAsync(id);if(x is null)return NotFound();x.CleanlinessScore=Math.Clamp(cleanlinessScore,0,10);x.SafetyScore=Math.Clamp(safetyScore,0,10);x.Findings=findings;x.CompletedOn=DateTime.UtcNow;x.InspectorUserId=UserId();x.Status=x.CleanlinessScore<6||x.SafetyScore<6?HostelInspectionStatus.FollowUpRequired:HostelInspectionStatus.Completed;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostDamageAsync(){var inspection=await db.HostelRoomInspections.SingleAsync(x=>x.Id==Damage.InspectionId);var damage=new HostelDamageAssessment{TenantId=inspection.TenantId,HostelRoomInspectionId=inspection.Id,HostelAllocationId=Damage.HostelAllocationId,Description=Damage.Description,EstimatedCost=Damage.EstimatedCost,ChargedAmount=Damage.ChargedAmount,StudentLiable=Damage.StudentLiable};FeeInvoice? invoice=null;if(damage.StudentLiable&&damage.ChargedAmount>0&&damage.HostelAllocationId.HasValue){var a=await db.HostelAllocations.SingleAsync(x=>x.Id==damage.HostelAllocationId);invoice=new FeeInvoice{TenantId=a.TenantId,BranchId=a.BranchId,StudentProfileId=a.StudentProfileId,InvoiceNumber=$"DMG-{DateTime.UtcNow:yyyyMMdd}-{damage.Id.ToString("N")[..6]}",InvoiceDate=DateOnly.FromDateTime(DateTime.UtcNow),DueDate=DateOnly.FromDateTime(DateTime.UtcNow.AddDays(10)),Status=InvoiceStatus.Issued,SubTotal=damage.ChargedAmount,TotalAmount=damage.ChargedAmount,Lines=[new(){TenantId=a.TenantId,BranchId=a.BranchId,Description=damage.Description,ComponentType=FeeComponentType.Hostel,Amount=damage.ChargedAmount}]};db.Add(invoice);damage.FeeInvoiceId=invoice.Id;}db.Add(damage);await db.SaveChangesAsync();if(invoice is not null)await finance.PostInvoiceAsync(invoice.Id);return RedirectToPage();}
 public async Task<IActionResult> OnPostClearanceAsync(){await service.StartClearanceAsync(Clearance.HostelAllocationId!.Value,Clearance.VacationFrom,Clearance.ExpectedReturnOn,Clearance.IsFinalCheckout);return RedirectToPage();}
 public async Task<IActionResult> OnPostClearItemAsync(Guid id,bool cleared,string? notes){var item=await db.HostelClearanceItems.FindAsync(id);if(item is null)return NotFound();item.IsCleared=cleared;item.Notes=notes;item.ClearedByUserId=UserId();item.ClearedOn=cleared?DateTime.UtcNow:null;var req=await db.HostelClearanceRequests.Include(x=>x.Items).SingleAsync(x=>x.Id==item.HostelClearanceRequestId);req.Status=req.Items.All(x=>x.IsCleared||x.Id==item.Id&&cleared)?HostelClearanceStatus.Cleared:HostelClearanceStatus.InProgress;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostCompleteClearanceAsync(Guid id){await service.CompleteClearanceAsync(id);return RedirectToPage();}
 private async Task Load(){Branches=await branchAccess.FilterBranchesAsync(User,await db.Branches.AsNoTracking().ToListAsync());var bids=Branches.Select(x=>x.Id).ToList();Blocks=await db.HostelBlocks.Where(x=>bids.Contains(x.BranchId)).ToListAsync();Rooms=await db.HostelRooms.Where(x=>bids.Contains(x.BranchId)).ToListAsync();Allocations=await db.HostelAllocations.Include(x=>x.StudentProfile).Include(x=>x.HostelRoom).Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.AllocatedOn).ToListAsync();var aids=Allocations.Select(x=>x.Id).ToList();Menus=await db.HostelMessMenus.Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.MenuDate).Take(100).ToListAsync();MessAttendance=await db.HostelMessAttendances.Where(x=>aids.Contains(x.HostelAllocationId)).OrderByDescending(x=>x.AttendanceDate).Take(100).ToListAsync();MessBills=await db.HostelMessBills.Include(x=>x.FeeInvoice).Where(x=>aids.Contains(x.HostelAllocationId)).OrderByDescending(x=>x.PeriodEnd).ToListAsync();Visitors=await db.HostelVisitorLogs.Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.CheckInOn).Take(100).ToListAsync();GatePasses=await db.HostelGatePasses.Include(x=>x.HostelAllocation)!.ThenInclude(x=>x!.StudentProfile).Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.PlannedOutOn).Take(100).ToListAsync();Maintenance=await db.HostelMaintenanceRequests.Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.ReportedOn).Take(100).ToListAsync();var mids=Maintenance.Select(x=>x.Id).ToList();Escalations=await db.HostelMaintenanceEscalations.Where(x=>mids.Contains(x.HostelMaintenanceRequestId)).OrderByDescending(x=>x.EscalatedOn).ToListAsync();Inspections=await db.HostelRoomInspections.Include(x=>x.Damages).Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.ScheduledOn).ToListAsync();Clearances=await db.HostelClearanceRequests.Include(x=>x.Items).Include(x=>x.HostelAllocation)!.ThenInclude(x=>x!.StudentProfile).Where(x=>bids.Contains(x.BranchId)).OrderByDescending(x=>x.RequestedOn).ToListAsync();var forecast=new List<OccupancyForecastRow>();foreach(var branchId in bids)forecast.AddRange(await service.ForecastAsync(branchId,DateOnly.FromDateTime(DateTime.UtcNow.AddDays(30))));Forecast=forecast;Menu.BranchId??=Branches.FirstOrDefault()?.Id;}
 private Guid? UserId()=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var id)?id:null;
}
